"use client";

import Link from "next/link";
import { useEffect, Suspense } from "react";
import { useCart } from "../../../context/CartContext"; // <-- Внимавай за точния път до CartContext
import { CheckCircle } from "lucide-react";

function SuccessContent() {
  const { clearCart } = useCart(); // <-- Взимаме функцията за чистене на количката

  useEffect(() => {
    // 1. ВЕДНАГА ИЗЧИСТВАМЕ КОЛИЧКАТА! 🧹
    clearCart();

    // 2. Отбелязваме поръчката като успешна в базата
    const params = new URLSearchParams(window.location.search);
    const orderId = params.get("orderId");

    if (orderId) {
      fetch(`http://localhost:5000/orders/${orderId}/success`, {
        method: "PUT"
      }).catch(err => console.error(err));
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="min-h-screen bg-[#0a0a0a] flex flex-col items-center justify-center text-white px-4 text-center">
      
      <div className="text-green-500 mb-8 animate-bounce bg-green-500/10 p-4 rounded-full border border-green-500/20 shadow-[0_0_30px_rgba(34,197,94,0.4)]">
        <CheckCircle size={64} strokeWidth={1.5} />
      </div>

      <h1 className="text-4xl md:text-5xl font-black uppercase tracking-tighter mb-4 italic">
        Успешно <span className="text-green-500">Плащане!</span>
      </h1>
      
      <p className="text-gray-400 max-w-lg mb-10 text-sm uppercase tracking-widest leading-relaxed">
        Благодарим ви, че избрахте Retro Audio. Поръчката ви е приета и се обработва.
      </p>

      <div className="flex gap-4">
        <Link href="/shop">
            <button className="px-8 py-4 bg-[#0a0a0a] border border-[#333] hover:border-[#ff6b00] hover:text-[#ff6b00] rounded-xl font-bold uppercase text-xs tracking-widest transition-all">
                Каталог
            </button>
        </Link>
        <Link href="/dashboard">
            <button className="px-8 py-4 bg-gradient-to-r from-[#ff6b00] to-[#e65c00] hover:from-[#e65c00] hover:to-[#cc5200] text-black rounded-xl font-black uppercase text-xs tracking-widest transition-all shadow-[0_5px_15px_rgba(255,107,0,0.3)] transform hover:-translate-y-1">
                Моите поръчки
            </button>
        </Link>
      </div>

    </div>
  );
}

export default function SuccessPage() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center text-[#ff6b00] font-bold animate-pulse tracking-widest">ЗАРЕЖДАНЕ...</div>}>
      <SuccessContent />
    </Suspense>
  );
}